const admListarPessoas = `-- name: AdmListarPessoas :many
SELECT p.id, p.nome, p.cpf, p.matricula, p.cargo, p.vinculo, p.fornecedor_id, p.unidade_id, p.situacao,
       p.versao, p.criado_em,
       u.id AS usuario_id
FROM app.pessoa p
LEFT JOIN app.usuario u ON u.empresa_id = p.empresa_id AND u.pessoa_id = p.id AND u.excluido_em IS NULL
WHERE p.empresa_id = $1 AND p.excluido_em IS NULL
  AND ($2::text IS NULL OR p.nome ILIKE $2::text)
  AND ($3::text IS NULL OR p.situacao = $3::text)
  AND ($4::uuid IS NULL OR p.fornecedor_id = $4::uuid)
  AND ($5::uuid IS NULL OR p.unidade_id = $5::uuid)
  AND ($6::boolean IS NULL OR (u.id IS NOT NULL) = $6::boolean)
  AND ($7::timestamptz IS NULL
       OR (p.criado_em, p.id) < ($7::timestamptz, $8::uuid))
ORDER BY p.criado_em DESC, p.id DESC
LIMIT $9
`

